MATCH (p:Painting {name: "Candlestick and Playing Cards on a Table"})-[:displayedAt]->(m:Museum)
MATCH (s:Sculpture)
RETURN s.name AS sculptureName, s.country_of_origin AS countryOfOrigin, m.name AS museumOfPainting

