MATCH (s:Sculpture)
RETURN s.name AS sculptureName, s.country_of_origin AS countryOfOrigin;

MATCH (person:Person)
WHERE toLower(person.name) CONTAINS toLower('Cardinal Gaspar Quiroga')
// Find the painting(s) linked to that person (e.g., created by the person)
MATCH (targetPaint:Painting)-[:createdBy]->(person)
// Locate the museum where the target painting is exhibited
MATCH (targetPaint)-[:displayedAt]->(museum:Museum)
// Retrieve all other paintings displayed at the same museum
MATCH (otherPaint:Painting)-[:displayedAt]->(museum)
WHERE otherPaint <> targetPaint
RETURN DISTINCT otherPaint.name AS name, otherPaint.creation_year AS creation_year
